import{_ as a,C as o,o as d,c,ag as t,E as n}from"./chunks/framework.Drp2S_UI.js";const _=JSON.parse('{"title":"架构与模块职责","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md","lastUpdated":1792653875000}'),i={name:"guide/architecture.md"};function s(l,e,h,u,p,m){const r=o("MermaidDiagram");return d(),c("div",null,[e[0]||(e[0]=t('<h1 id="架构与模块职责" tabindex="-1">架构与模块职责 <a class="header-anchor" href="#架构与模块职责" aria-label="Permalink to &quot;架构与模块职责&quot;">​</a></h1><p>本页描述 <code>@herberthe/canvas-editor</code> 0.1.0 的当前实现。文字由 HarfBuzz 统一整形，页面由 Canvas 绘制；不存在 legacy 文字排版回退、UMD 包或可切换的 SVG 页面后端。完整执行过程见<a href="./rendering-pipeline.html">渲染管线与时序</a>。</p><h2 id="分层视图" tabindex="-1">分层视图 <a class="header-anchor" href="#分层视图" aria-label="Permalink to &quot;分层视图&quot;">​</a></h2>',3)),n(r,{code:`flowchart TB
  Host[宿主应用：工具栏、存储、业务表单] --> API[Editor / Command / Register / EventBus]
  API --> Lifecycle[EditorLifecycle：异步初始化与状态保护]
  API --> Model[文档元素 / Range / History]
  Model --> Draw[Draw：渲染调度、脏区与页面管理]
  Draw --> HostLayout[LayoutHostAdapter / 原生容器布局]
  HostLayout --> Text[TextLayoutService / TextLayoutEngine]
  Text --> Bidi[BiDi、脚本与样式分段]
  Bidi --> HB[HarfBuzzTextShaper]
  HB --> Fonts[FontManager / HarfBuzzRuntime]
  HostLayout --> Geometry[TextLine / Cluster / Caret / 对象与页面几何]
  Geometry --> Paint[GlyphRenderer / 对象绘制 / Canvas]
  Geometry --> Interaction[命中测试、选区、光标与键盘导航]
  Fonts --> Coverage[覆盖诊断 / FontDownloadManager]
  Coverage --> Draw
`}),e[1]||(e[1]=t('<p>图中箭头表示职责与数据依赖，不代表每个模块都在独立线程运行。当前 HarfBuzz 排版在主线程执行；已有 Worker 负责字数、序列化等辅助任务，不是文字排版 Worker。</p><h2 id="模块索引" tabindex="-1">模块索引 <a class="header-anchor" href="#模块索引" aria-label="Permalink to &quot;模块索引&quot;">​</a></h2><p>以下路径相对于仓库根目录，属于内部实现，不能作为 npm 深路径导入。</p><table tabindex="0"><thead><tr><th>模块</th><th>主要位置</th><th>职责</th></tr></thead><tbody><tr><td>公开入口</td><td><code>src/editor/index.ts</code></td><td>数据标准化、模块组装、create/ready、销毁、公开导出</td></tr><tr><td>生命周期</td><td><code>src/editor/core/EditorLifecycle.ts</code></td><td>初始化/就绪/失败/销毁状态，命令时机保护</td></tr><tr><td>命令</td><td><code>src/editor/core/command/</code></td><td>对外操作入口、选区修改、格式与文档命令</td></tr><tr><td>渲染调度</td><td><code>src/editor/core/draw/Draw.ts</code></td><td>消费脏区、容器布局、分页、位置、页面与绘制调度</td></tr><tr><td>原生布局宿主</td><td><code>src/editor/core/text-engine-host/</code></td><td>段落桥接、表格、对象、页眉页脚与文档流</td></tr><tr><td>文字整形</td><td><code>src/editor/core/text-engine/</code></td><td>字体字节、BiDi、HarfBuzz、断行、字形轮廓与诊断</td></tr><tr><td>原生几何协议</td><td><code>src/editor/core/layout/</code>、<code>src/editor/interface/Layout.ts</code></td><td>行、glyph、cluster、caret、容器和对象的统一几何</td></tr><tr><td>交互</td><td><code>src/editor/core/position/</code>、<code>core/range/</code>、<code>core/listener/</code></td><td>输入事件、命中、选区、光标和键盘行为</td></tr><tr><td>数据与扩展</td><td><code>src/editor/interface/</code>、<code>src/plugins/</code></td><td>公开类型、文档模型与插件接入</td></tr></tbody></table><h2 id="三类数据不能混用" tabindex="-1">三类数据不能混用 <a class="header-anchor" href="#三类数据不能混用" aria-label="Permalink to &quot;三类数据不能混用&quot;">​</a></h2><ol><li><strong>持久化文档</strong>：<code>IEditorData</code> 中的 header/main/footer 与元素样式、表格和控件信息。保存业务内容时使用 <code>command.getValue()</code> 的结果，不保存内部坐标和字体对象。</li><li><strong>运行期元素</strong>：标准化、拆分后的元素与逻辑来源，用于编辑、历史和布局桥接。不能把运行期数组下标等同于 UTF-16 字符下标；组合文字、代理对、控件与段落标记会影响映射。</li><li><strong>布局几何</strong>：TextLine、glyph、cluster、caret、内联对象及分页位置。几何来源于当前字体版本、宽度与排版结果，字体或约束变化后必须重新计算。</li></ol><p>内部 <code>LayoutRow</code> 仍承担容器流与宿主兼容职责；名称中保留 row 不代表旧文字测量循环仍在运行。公开查询返回的行快照是脱离内部对象的兼容 DTO，不是下一轮布局输入。</p><h2 id="文字、容器与绘制的分工" tabindex="-1">文字、容器与绘制的分工 <a class="header-anchor" href="#文字、容器与绘制的分工" aria-label="Permalink to &quot;文字、容器与绘制的分工&quot;">​</a></h2><p>HarfBuzz 负责上下文整形，给出 glyph ID、cluster、advance 和 offset；它不负责整篇编辑器的分页、表格拆页或工具栏。TextLayoutEngine 结合双向分析、字体选择与断行规则生成行；TextLayoutService 将字体度量与墨迹边界转成基线、行框、cluster 和 caret。</p><p>段落布局之外，容器宿主处理页宽、分栏、浮动图环绕、表格单元格和跨页分片，文档流组合页眉、正文与页脚。GlyphRenderer 使用真实字体的字形轮廓绘制文字；图片、公式、控件外观和块对象仍有专用绘制逻辑。DOM 继续承载输入代理、工具浮层和无障碍提示，因此 Canvas-only 指的是文档页面绘制方式，不代表整个应用没有 DOM。</p><h2 id="状态、事件与历史" tabindex="-1">状态、事件与历史 <a class="header-anchor" href="#状态、事件与历史" aria-label="Permalink to &quot;状态、事件与历史&quot;">​</a></h2><p><code>EditorLifecycle</code> 将初始化失败与缺字分开：前者使 ready 拒绝，后者保留可编辑的缺字占位并输出诊断。字体下载完成会改变字体版本，触发布局失效和重新绘制，不是直接替换 Canvas 上的几个字符。</p><p>Command 负责业务操作，History 保存文档与选区等状态以支持撤销重做。它不是 CRDT 或协同操作日志。Listener 是单回调槽，EventBus 支持多个订阅者；宿主销毁时需清理自己的订阅、工具栏和外部资源。</p><h2 id="扩展与性能边界" tabindex="-1">扩展与性能边界 <a class="header-anchor" href="#扩展与性能边界" aria-label="Permalink to &quot;扩展与性能边界&quot;">​</a></h2><p>应用通过包根公开 API 集成。插件如需操作内部 Draw、旧行坐标或浏览器字体测量，必须重新适配；上游插件不能仅因包名相近就认为兼容。字体与 ESM 迁移见<a href="./font-and-esm-migration.html">迁移指南</a>。</p><p><code>lab.incrementalCompute</code> 默认关闭，开启后复用未变化段落的原生布局，仍需重建文档流、分页和位置。单个长段落的上下文整形、缓存克隆与全局流处理可能使增量更慢。<a href="./native-release-acceptance.html">最终验收</a>记录了 T23/T24 的实际结果，性能目标与未来 SVG 设计不等于已交付能力。</p>',16))])}const g=a(i,[["render",s]]);export{_ as __pageData,g as default};
